using Godot;
using System;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorScreenRecorderOperations:RefCounted
{
    private readonly ActorVideoOperations _video=new();private readonly ActorDataOperations _data=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static Settings Process(Node owner)=>owner.Get("process").AsGodotDictionary();private static string Text(Node owner,string key)=>owner.Get(key).AsString();
    private static string Output(GArray output){var text=new StringBuilder();foreach(var value in output)text.Append(value.AsString());return text.ToString();}
    private static Rect2I Desktop(){var desktop=new Rect2I();for(int i=0;i<DisplayServer.GetScreenCount();i++){var area=new Rect2I(DisplayServer.ScreenGetPosition(i),DisplayServer.ScreenGetSize(i));desktop=i==0?area:desktop.Merge(area);}return desktop;}
    public Godot.Collections.Array<Settings> targets()
    {
        var result=new Godot.Collections.Array<Settings>{new Settings{["label"]="Entire desktop (all displays)",["input"]="desktop",["category"]="Entire display"}};var desktop=Desktop();for(int i=0;i<DisplayServer.GetScreenCount();i++)result.Add(new Settings{["label"]="Display "+(i+1),["input"]="desktop",["category"]="Entire display",["position"]=DisplayServer.ScreenGetPosition(i),["size"]=DisplayServer.ScreenGetSize(i)});if(desktop.HasArea()){result[0]["position"]=desktop.Position;result[0]["size"]=desktop.Size;}
        if(OS.GetName()=="Windows"&&DisplayServer.GetName()!="headless"){var output=new GArray();OS.Execute("powershell.exe",new[]{"-NoProfile","-NonInteractive","-Command",@"@(Get-Process | Where-Object { $_.MainWindowHandle -ne 0 -and $_.MainWindowTitle } | Select-Object @{n='label';e={$_.MainWindowTitle}},@{n='input';e={'hwnd=' + $_.MainWindowHandle.ToInt64()}}) | ConvertTo-Json -Compress"},output);var parsed=Json.ParseString(Output(output));var windows=parsed.VariantType==Variant.Type.Dictionary?new GArray{parsed}:parsed.VariantType==Variant.Type.Array?parsed.AsGodotArray():new GArray();foreach(var value in windows)if(value.VariantType==Variant.Type.Dictionary){var entry=value.AsGodotDictionary();entry["category"]="Windows";result.Add(entry);}}return result;
    }
    public string[] capture_arguments(Settings target,int fps,bool cursor,int resolution)
    {
        var args=new List<string>{"-hide_banner","-loglevel","error","-n","-f","gdigrab","-framerate",fps.ToString(CultureInfo.InvariantCulture),"-draw_mouse",cursor?"1":"0"};if(target.ContainsKey("position")&&target.ContainsKey("size")){var position=target["position"].AsVector2I();var size=target["size"].AsVector2I();args.AddRange(new[]{"-offset_x",position.X.ToString(CultureInfo.InvariantCulture),"-offset_y",position.Y.ToString(CultureInfo.InvariantCulture),"-video_size",size.X+"x"+size.Y});}string filter="pad=ceil(iw/2)*2:ceil(ih/2)*2";if(resolution>0)filter="scale=-2:"+resolution+":flags=lanczos,"+filter;args.AddRange(new[]{"-i",Get(target,"input","desktop").AsString(),"-vf",filter,"-c:v","libx264","-preset","ultrafast","-crf","16","-pix_fmt","yuv420p","-movflags","+frag_keyframe+empty_moov"});return args.ToArray();
    }
    public Settings prepare_start(Node owner,Settings options,Settings target)
    {
        Settings Failure(string message)=>new Settings{["error"]=message};if(owner.Get("recording").AsBool())return Failure("Already recording.");if(OS.GetName()!="Windows"||DisplayServer.GetName()=="headless")return Failure("Screen recording requires the Windows desktop.");string encoder=_video.executable("ffmpeg");if(encoder.Length==0)return Failure("FFmpeg is required for screen recording.");target=target.Duplicate();string input=Get(target,"input","").AsString();if(input.StartsWith("hwnd=",StringComparison.Ordinal)){var output=new GArray();var args=new List<string>{"-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-File",ProjectSettings.GlobalizePath("res://scripts/actors/core/screen_capture_window.ps1"),"-WindowHandle",input.Substring(5)};if(target.ContainsKey("tab_name"))args.AddRange(new[]{"-TabName",target["tab_name"].AsString()});OS.Execute("powershell.exe",args.ToArray(),output);var parsed=Json.ParseString(Output(output));if(parsed.VariantType!=Variant.Type.Dictionary)return Failure("The selected window is no longer available.");var bounds=parsed.AsGodotDictionary();if(bounds["width"].AsInt32()<=0||bounds["height"].AsInt32()<=0)return Failure("The selected window is no longer available.");var area=new Rect2I(new Vector2I(bounds["x"].AsInt32(),bounds["y"].AsInt32()),new Vector2I(bounds["width"].AsInt32(),bounds["height"].AsInt32())).Intersection(Desktop());if(!area.HasArea())return Failure("The selected window is outside the visible desktop.");target["input"]="desktop";target["position"]=area.Position;target["size"]=area.Size;}
        string directory=ProjectSettings.GlobalizePath("user://screen_recordings/"+_data.new_id());owner.Set("directory",directory);DirAccess.MakeDirRecursiveAbsolute(directory);if(Get(options,"record_mic",false).AsBool()||Get(options,"record_system",false).AsBool()||Get(options,"record_timeline",false).AsBool()){var audio=new ActorAudioRecorder();audio.Set("preferences_override",options.Duplicate());owner.Set("audio_recorder",audio);owner.AddChild(audio);}return new Settings{["error"]="",["encoder"]=encoder,["target"]=target,["audio_started"]=Time.GetTicksMsec()};
    }
    public Settings begin_capture(Node owner,Settings request,Settings options,string audioError)
    {
        if(audioError.Length>0){cleanup(owner);return new Settings{["error"]=audioError};}ulong started=owner.Get("audio_recorder").AsGodotObject()!=null?Time.GetTicksMsec():request["audio_started"].AsUInt64();var args=new List<string>(capture_arguments(request["target"].AsGodotDictionary(),Get(options,"screen_fps",30).AsInt32(),Get(options,"screen_cursor",true).AsBool(),Get(options,"screen_resolution",0).AsInt32()));string path=Text(owner,"directory").PathJoin("capture.mp4");owner.Set("output_path",path);args.Add(path);var process=OS.ExecuteWithPipe(request["encoder"].AsString(),args.ToArray(),false);owner.Set("process",process);if(process.Count==0){cleanup(owner);return new Settings{["error"]="Screen capture could not start."};}return new Settings{["error"]="",["deadline"]=Time.GetTicksMsec()+10000,["audio_started"]=started};
    }
    public bool startup_pending(Node owner,ulong deadline){var process=Process(owner);bool pending=process.ContainsKey("pid")&&OS.IsProcessRunning(process["pid"].AsInt32())&&!Godot.FileAccess.FileExists(Text(owner,"output_path"))&&Time.GetTicksMsec()<deadline;if(pending)drain_errors(owner);return pending;}
    public string complete_start(Node owner,ulong started){var process=Process(owner);if(!process.ContainsKey("pid")||!OS.IsProcessRunning(process["pid"].AsInt32())||!Godot.FileAccess.FileExists(Text(owner,"output_path"))){drain_errors(owner);string error="Screen capture failed. "+Text(owner,"last_error");cleanup(owner);return error;}owner.Set("_audio_lead",(Time.GetTicksMsec()-started)/1000.0);owner.Set("recording",true);return "";}
    public void drain_errors(Node owner){var process=Process(owner);if(!process.TryGetValue("stderr",out var pipe))return;var bytes=pipe.As<Godot.FileAccess>().GetBuffer(4096);if(bytes.Length==0)return;string error=Text(owner,"last_error")+Encoding.UTF8.GetString(bytes);var runes=error.EnumerateRunes().ToArray();owner.Set("last_error",runes.Length<=2000?error:string.Concat(runes.Skip(runes.Length-2000).Select(rune=>rune.ToString())));}
    public ulong prepare_stop(Node owner){if(!owner.Get("recording").AsBool())return 0;owner.Set("recording",false);var process=Process(owner);if(OS.IsProcessRunning(process["pid"].AsInt32()))process["stdio"].As<Godot.FileAccess>().StoreString("q\n");return Time.GetTicksMsec()+10000;}
    public bool stop_pending(Node owner,ulong deadline){bool pending=OS.IsProcessRunning(Process(owner)["pid"].AsInt32())&&Time.GetTicksMsec()<deadline;if(pending)drain_errors(owner);return pending;}
    public void finish_capture(Node owner){var process=Process(owner);if(OS.IsProcessRunning(process["pid"].AsInt32()))OS.Kill(process["pid"].AsInt32());process.Clear();}
    public Settings prepare_mux(Node owner,AudioStreamWav? audio)
    {
        if(audio==null)return new Settings();string wav=Text(owner,"directory").PathJoin("audio.wav");if(audio.SaveToWav(wav)!=Error.Ok)return new Settings();string merged=Text(owner,"directory").PathJoin("recording.mp4");var args=new[]{"-nostdin","-v","error","-n","-i",Text(owner,"output_path"),"-ss",owner.Get("_audio_lead").AsDouble().ToString("R",CultureInfo.InvariantCulture),"-i",wav,"-map","0:v:0","-map","1:a:0","-c:v","copy","-af","apad","-c:a","aac","-shortest",merged};var job=OS.ExecuteWithPipe(_video.executable("ffmpeg"),args,false);if(job.Count>0)owner.Set("process",job);return new Settings{["job"]=job,["wav"]=wav,["merged"]=merged};
    }
    public bool mux_pending(Settings request){var job=request["job"].AsGodotDictionary();if(job.Count==0||!OS.IsProcessRunning(job["pid"].AsInt32()))return false;job["stderr"].As<Godot.FileAccess>().GetBuffer(4096);return true;}
    public void complete_mux(Node owner,Settings request){var job=request["job"].AsGodotDictionary();if(job.Count>0){if(OS.GetProcessExitCode(job["pid"].AsInt32())==0&&Godot.FileAccess.FileExists(request["merged"].AsString()))owner.Set("output_path",request["merged"]);Process(owner).Clear();}DirAccess.RemoveAbsolute(request["wav"].AsString());}
    public string finish_stop(Node owner){string path=Text(owner,"output_path");string result=GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("info",path).AsGodotDictionary().Count>0?path:"";cleanup(owner);return result;}
    public void cleanup(Node owner){owner.Set("recording",false);var process=Process(owner);if(process.TryGetValue("pid",out var pid)&&OS.IsProcessRunning(pid.AsInt32()))OS.Kill(pid.AsInt32());process.Clear();var audio=owner.Get("audio_recorder").AsGodotObject();if(GodotObject.IsInstanceValid(audio)&&audio is Node node){node.Call("_cleanup");node.QueueFree();}owner.Set("audio_recorder",default(Variant));}
}
